package com.vahotel.service;
import com.vahotel.model.*;import com.vahotel.repo.*;import java.math.BigDecimal;import java.time.LocalDate;import java.time.temporal.ChronoUnit;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class ReservationService {private final ReservationRepository reservations;public ReservationService(ReservationRepository r){reservations=r;}
 @Transactional public Reservation create(Account customer,Room room,LocalDate in,LocalDate out){if(in==null||out==null||!in.isAfter(LocalDate.now(java.time.ZoneId.of("Asia/Manila")))||!out.isAfter(in))throw new IllegalArgumentException("Select a valid future check-in and later check-out date.");if(!room.isActive())throw new IllegalArgumentException("Room is inactive.");if(reservations.countOverlaps(room,in,out)>0)throw new IllegalStateException("Room has an overlapping reservation.");long nights=ChronoUnit.DAYS.between(in,out);BigDecimal total=room.getNightlyPrice().multiply(BigDecimal.valueOf(nights));return reservations.save(new Reservation(customer,room,in,out,"REGULAR",total));}}
